document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("tile-form"),t=document.getElementById("tile-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("tile-area").value),a=parseFloat(document.getElementById("tile-length").value),s=parseFloat(document.getElementById("tile-width").value),o=parseFloat(document.getElementById("tile-waste").value);if(n<=0||a<=0||s<=0)return t.textContent="Please enter all parameters with positive values.",void 0;const l=a*s/144;let i=n/l;const r=i*(1+o/100),d=Math.ceil(n*(1+o/100)/10),c=n*(1+o/100);t.innerHTML=`\n        <div class="result-section">\n          <h4>Tiles Needed:</h4>\n          <p><strong>${Math.ceil(i)} tiles</strong> (exact calculation)</p>\n          <p><strong>${Math.ceil(r)} tiles</strong> (with ${o}% waste factor)</p>\n        </div>\n        <div class="result-coverage">\n          <h4>Coverage & Ordering:</h4>\n          <p>Area to cover: ${n} sq ft</p>\n          <p>Total material needed: ${c.toFixed(1)} sq ft</p>\n          <p>Tile size: ${a}" × ${s}" (${l.toFixed(3)} sq ft each)</p>\n          <p>Estimated boxes needed: ${d} boxes (assuming 10 sq ft/box)</p>\n        </div>\n        <div class="result-tips">\n          <p><em>💡 Order from the same production lot to ensure color consistency</em></p>\n          <p><em>📦 Check actual box coverage - varies by manufacturer (8-20 sq ft typical)</em></p>\n          <p><em>🔧 Consider ordering extra for complex cuts and future repairs</em></p>\n        </div>\n      `})});